import { describe, expect, it } from "vitest";

import {
  parseTimeframe,
  TrafficFrameResponseSchema,
} from "./trafficService.ts";

// Fixtures are generated by `cargo test --test serialize_fixtures` in
// src-tauri from the real serde output of traffic::FrameResponse.
// When the Rust type changes, re-run that test to regenerate; if this file
// then fails, update TrafficFrameResponseSchema to match the new wire format.
import frame from "./fixtures/traffic_frame.json";
import failed from "./fixtures/traffic_frame_failed.json";

describe("TrafficFrameResponseSchema fixtures", () => {
  it("parses a running capture", () => {
    const parsed = TrafficFrameResponseSchema.safeParse(frame);
    expect(parsed.success).toBe(true);
    if (!parsed.success) return;
    expect(parsed.data.capture.active).toBe(true);
    expect(parsed.data.capture.interface).toBe("en0");
    expect(parsed.data.frame.timeframe_seconds).toBe(5);
    expect(parsed.data.frame.cells).toHaveLength(3);
    expect(parsed.data.frame.cells[0].class).toBe("hopr_associated");
    expect(parsed.data.frame.cells[2].class).toBe("other");
    // Newest upstream block sits in the first column, newest downstream in the last.
    expect(parsed.data.frame.cells[0].column).toBe(0);
    expect(parsed.data.frame.cells[1].column).toBe(4);
  });

  it("parses a failed capture with no rows", () => {
    const parsed = TrafficFrameResponseSchema.safeParse(failed);
    expect(parsed.success).toBe(true);
    if (!parsed.success) return;
    expect(parsed.data.capture.active).toBe(false);
    expect(parsed.data.capture.interface).toBeNull();
    expect(parsed.data.capture.error).toBe(
      "The Gnosis VPN service is not running",
    );
    expect(parsed.data.frame.total_rows).toBe(0);
    expect(parsed.data.gap).toBe(true);
  });

  it("rejects out-of-range bands and unknown categories", () => {
    const base = JSON.parse(JSON.stringify(frame));
    base.frame.cells[0].band = 7;
    expect(TrafficFrameResponseSchema.safeParse(base).success).toBe(false);

    // Deliberately invalid for the schema under test.
    const unknown = JSON.parse(JSON.stringify(frame));
    unknown.frame.cells[0].class = "mixnet";
    expect(TrafficFrameResponseSchema.safeParse(unknown).success).toBe(false);
  });
});

describe("parseTimeframe", () => {
  it("accepts whole seconds in range", () => {
    expect(parseTimeframe("1")).toBe(1);
    expect(parseTimeframe(" 20 ")).toBe(20);
    expect(parseTimeframe("300")).toBe(300);
  });

  it("rejects everything else without changing the window", () => {
    for (const raw of ["", "0", "301", "-5", "2.5", "abc", "1e3", "20s"]) {
      expect(parseTimeframe(raw)).toBeNull();
    }
  });
});
